"""Module contains Span interface."""

from abc import ABC, abstractmethod
from typing import Optional, Any


class BaseSpan(ABC):
    """Base class for all spans."""
    @abstractmethod
    def reset_status(self):
        """Set span status to UNSET.

        This marks the span as implicitly completed successfully."""

    @abstractmethod
    def set_status_ok(self):
        """Set span status to OK.

        This marks the span as explicitly completed successfully."""

    @abstractmethod
    def set_status_error(self, description: Optional[str] = None):
        """Set span status to ERROR.

        :param description: Reason for error, defaults to None.
        """

    @abstractmethod
    def set_attributes(self, attributes):
        """Add additional span attributes."""

    @abstractmethod
    def record_exception(self, exception: Exception, attributes=None, escaped: bool = False):
        """Record exception in span.

        :param exception: Exception to save in span.
        :param attributes: Additional span attributes, defaults to None.
        :param escaped: _description_, defaults to False.
        """

    @abstractmethod
    def add_event(self, name: str, attributes=None):
        """Mark an incident in span.

        :param name: Incident name.
        :param attributes: Additional span attributes, defaults to None.
        """


class NoOpSpan(BaseSpan):
    """Empty Span interface - used when Telemetry is unavailable and cannot be used."""
    def reset_status(self):
        ...

    def set_status_ok(self):
        ...

    def set_status_error(self, description: Optional[str] = None):
        ...

    def set_attributes(self, attributes):
        ...

    def record_exception(self, exception: Exception, attributes=None, escaped: bool = False):
        ...

    def add_event(self, name: str, attributes=None):
        ...


class Span(BaseSpan):
    """Regular Span interface"""
    def __init__(self, span: Any):
        self._span = span

    def reset_status(self):
        from opentelemetry import trace
        self._span.set_status(trace.StatusCode.UNSET)

    def set_status_ok(self):
        from opentelemetry import trace
        self._span.set_status(trace.StatusCode.OK)

    def set_status_error(self, description: Optional[str] = None):
        from opentelemetry import trace
        self._span.set_status(trace.StatusCode.ERROR, description)

    def set_attributes(self, attributes):
        self._span.set_attributes(attributes)

    def record_exception(self, exception: Exception, attributes=None, escaped: bool = False):
        self._span.record_exception(exception, attributes, escaped=escaped)

    def add_event(self, name: str, attributes=None):
        self._span.add_event(name, attributes)
